            // currentInspect goes with it. The axis controls still hold the
            // pair, so read them before giving up; and when even they are
            // empty, say the axes were not recorded rather than writing "?",
            // which a reader can only quote back as a gene called "?".
            const _axG = (id) => (document.getElementById(id)?.value || '').trim().toUpperCase();
            const g1 = ci?.gene1 || _axG('inspectGeneX');
            const g2 = ci?.gene2 || _axG('inspectGeneY');
            const t1 = ci?.xType || document.getElementById('xAxisDataType')?.value;
            const t2 = ci?.yType || document.getElementById('yAxisDataType')?.value;
            const axesKnown = !!(g1 && g2);
            const xLabel = axesKnown ? `${g1} ${typeLabel(t1)}` : 'an axis this file did not record';
            const yLabel = axesKnown ? `${g2} ${typeLabel(t2)}` : 'an axis this file did not record';
            if (axesKnown) { context.gene1 = g1; context.gene2 = g2; context.xType = t1 || 'ge'; context.yType = t2 || 'ge'; }
            else context.axesNotRecorded = 'The plot this file came from was closed before the export ran, so which genes were on the axes was not captured. The companion image still shows the plot; read the axis titles off it, and do not guess from the gene list, which is the export\'s own selection rather than the plot\'s axes.';
            const parts = [
                cancerF,
                subF,
                context.mutationFilter,
                context.fusionFilter,
                customCLCount ? `custom CL list (n=${customCLCount})` : ''
            ].filter(Boolean);
            context.plotDescribesWhat = `A scatter plot. Each point is a cell line. X axis is ${xLabel}, Y axis is ${yLabel}. ${n.toLocaleString()} points.`
                + (colorBy ? ` Points are coloured by ${colorBy}.` : '')
                + (clickedLabelled?.length ? ` ${clickedLabelled.length} point(s) carry a visible name label because they were clicked on screen; every other point is unlabelled but present.` : '')
                + (this._gateFilter ? ` Only the cell lines inside gate ${this._gateFilter.gate} are plotted; the rest of the panel is excluded.` : '');
